SELECT COUNT(*) FROM (
    SELECT f.userregistry
    FROM fans f
    LEFT JOIN membershipandspending m ON f.userregistry = m.memberfanpivot
    LEFT JOIN interactions i ON f.userregistry = i.interactfanpivot
    WHERE EXISTS (
        SELECT 1 FROM interactions i2 WHERE i2.interactfanpivot = f.userregistry AND i2.giftvalusd > 500
    ) OR EXISTS (
        SELECT 1 FROM membershipandspending m2 WHERE m2.memberfanpivot = f.userregistry AND m2.spendusd > 1000
    )
) sub;

SELECT COUNT(DISTINCT f.userregistry) FROM fans f
WHERE EXISTS (
    SELECT 1 FROM interactions i2 WHERE i2.interactfanpivot = f.userregistry AND i2.giftvalusd > 500
) OR EXISTS (
    SELECT 1 FROM membershipandspending m2 WHERE m2.memberfanpivot = f.userregistry AND m2.spendusd > 1000
);

